        self.assertEqual(game_with([0] * 20).score(), 0)

    def test_open_frames(self):
        self.assertEqual(game_with([3, 6] * 10).score(), 90)

    def test_spare_then_open(self):
        self.assertEqual(game_with([6, 4, 3] + [0] * 17).score(), 16)

    def test_strike_then_open(self):
        self.assertEqual(game_with([10, 5, 3] + [0] * 16).score(), 26)

    def test_consecutive_strikes(self):
        self.assertEqual(game_with([10, 10, 10, 5, 3] + [0] * 12).score(), 81)

    def test_tenth_frame_spare_fill(self):
        self.assertEqual(game_with([0] * 18 + [7, 3, 10]).score(), 20)

    def test_tenth_frame_strike_spare(self):
        self.assertEqual(game_with([0] * 18 + [10, 7, 3]).score(), 20)

    def test_perfect_game(self):
        self.assertEqual(game_with([10] * 12).score(), 300)

    def test_strike_in_fill_after_spare(self):
        self.assertEqual(game_with([0] * 18 + [7, 3, 10]).score(), 20)

